-- not this
UPDATE driver_shifts SET ended_at = $1 WHERE id = $2;

-- this
INSERT INTO shift_events (shift_id, kind, payload, recorded_at, recorded_by, supersedes)
VALUES ($1, 'shift_ended', $2, now(), $3, $4);

ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON invoices
  USING (tenant_id = current_setting('app.tenant_id')::uuid);

-- set once per connection, in middleware
SET LOCAL app.tenant_id = '...';

const extracted = await model.extract(document);

const issues = [
  sumsMatch(extracted) ? null : 'line items do not sum to total',
  knownSupplier(extracted.supplierId) ? null : 'unknown supplier',
  dateWithinRange(extracted.issuedAt) ? null : 'implausible date',
].filter(Boolean);

if (issues.length) return queueForReview(extracted, issues);
return commit(extracted);

let missed = 0;

setInterval(() => {
  if (missed >= 2) return hardReconnect();   // we decide it's dead
  missed += 1;
  socket.send(JSON.stringify({ t: 'ping' }));
}, 15000);

onMessage((m) => { if (m.t === 'pong') missed = 0; });

const delay = Math.min(30000, 500 * 2 ** attempt);
const jittered = delay * (0.5 + Math.random() * 0.5);
setTimeout(connect, jittered);

socket.onclose = (e) => {
  if (e.code === 4401) return redirectToLogin();  // auth is gone, don't retry
  scheduleReconnect();                            // anything else, back off and retry
};
